<template>
  <div :class="presentation ? 'fixed inset-0 z-50 overflow-y-auto bg-base-100 p-8' : 'space-y-5'">
    <div v-if="!presentation" class="breadcrumbs text-sm"><ul><li><NuxtLink to="/spoc-agendas">SPOC agendas</NuxtLink></li><li>{{ agenda?.agenda_number || 'Agenda' }}</li></ul></div>
    <div v-if="loading" class="flex justify-center py-20"><span class="loading loading-spinner loading-lg" /></div>
    <template v-else-if="agenda">
      <header class="rounded-2xl border border-base-200 bg-base-100 p-5 shadow-sm"><div class="flex flex-wrap items-start justify-between gap-4"><div><div class="flex gap-2"><span class="badge badge-primary">{{ label(agenda.mode) }}</span><span class="badge">{{ label(agenda.status) }}</span></div><h1 :class="['mt-3 font-bold', presentation ? 'text-4xl' : 'text-2xl']">{{ agenda.title }}</h1><p class="font-mono text-sm text-base-content/50">{{ agenda.agenda_number }}</p></div><div class="flex flex-wrap gap-2"><button v-if="agenda.mode === 'SITTING'" class="btn btn-outline btn-sm" @click="presentation = !presentation"><Icon :name="presentation ? 'lucide:minimize-2' : 'lucide:presentation'" />{{ presentation ? 'Exit presentation' : 'Presentation mode' }}</button><button v-if="agenda.status === 'DRAFT'" class="btn btn-primary btn-sm" @click="publish">Publish agenda</button><button v-if="agenda.status === 'SCHEDULED'" class="btn btn-primary btn-sm" @click="start">Start sitting</button></div></div></header>
      <div class="mt-5 space-y-5"><article v-for="(entry, index) in agenda.items" :key="entry.id" class="rounded-2xl border border-base-200 bg-base-100 p-6 shadow-sm"><div class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-sm font-bold text-primary">ITEM {{ index + 1 }}</p><h2 :class="['mt-1 font-bold', presentation ? 'text-3xl' : 'text-xl']">{{ entry.case?.submission?.tender?.title }}</h2><p class="text-sm text-base-content/60">{{ entry.case?.submission?.tender?.tendernumber }} · {{ entry.case?.submission?.tender?.company?.name }}</p></div><NuxtLink :to="`/spoc-submissions/${entry.case?.submission?.uuid}`" class="btn btn-outline btn-sm">Open full case</NuxtLink></div><div class="mt-5 grid gap-4 md:grid-cols-3"><SpocReview title="Procurement Specialist" :decision="entry.case?.submission?.specialist_recommendation" :directive="entry.case?.submission?.specialist_directive" :comments="entry.case?.submission?.specialist_observations" /><SpocReview title="Assigning Manager" :decision="entry.case?.submission?.manager_recommendation" :directive="entry.case?.submission?.manager_directive" :comments="entry.case?.submission?.manager_comments" /><SpocReview title="Presenting Director" :decision="entry.case?.submission?.director_recommendation" :directive="entry.case?.submission?.director_directive" :comments="entry.case?.submission?.director_comments" /></div></article></div>
    </template>
  </div>
</template>
<script setup>
definePageMeta({ layout: 'default' }); const route = useRoute(); const api = useSpocWorkflowHelper(); const toast = useToast(); const agenda = ref(null); const loading = ref(true); const presentation = ref(false);
const label = value => String(value || '—').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
const load = async () => { loading.value = true; const { data, error } = await api.agenda(route.params.uuid); loading.value = false; if (error) return toast.error({ title: 'Could not load agenda', message: error?.data?.message }); agenda.value = data.data; useHead({ title: agenda.value.agenda_number }); };
const publish = async () => { const { error } = await api.publishAgenda(agenda.value.uuid); if (error) return toast.error({ title: 'Could not publish agenda', message: error?.data?.message }); await load(); };
const start = async () => { const { error } = await api.startAgenda(agenda.value.uuid); if (error) return toast.error({ title: 'Could not start agenda', message: error?.data?.message }); presentation.value = true; await load(); };
onMounted(load);
</script>
